def sift_down(a, i, n):
    swaps = 0
    while True:
        left = 2 * i + 1
        right = left + 1
        if left >= n:
            return swaps
        if a[left] < a[i]:
            a[i], a[left] = a[left], a[i]
            i = left
            swaps += 1
        elif right < n and a[right] < a[i]:
            a[i], a[right] = a[right], a[i]
            i = right
