def top_k(nums, k):
    if k <= 0:
        return []
    heap = []                             # the k largest seen so far; heap[0] is the smallest of them
    for x in nums:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heapreplace(heap, x)    # drop the smallest kept value, keep x
    return sorted(heap, reverse=True)

