        self.key, self.left, self.right, self.h = key, None, None, 0

def height(n):
    return -1 if n is None else n.h

def fix(n):
    n.h = 1 + max(height(n.left), height(n.right))

def rot_right(y):
    x = y.left
    y.left = x.right
    x.right = y
    fix(y); fix(x)
    return x

def rot_left(x):
    y = x.right
    x.right = y.left
    y.left = x
    fix(x); fix(y)
    return y

